import jakarta.persistence.*;
import java.time.LocalDateTime;

@Entity
@Table(name = "products")
public class Product {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false, length = 100)
    private String name;

    private Double price;

    private LocalDateTime createdAt;

    // JPA requires this no-arg constructor
    protected Product() {}

    public Product(String name, Double price) {
        this.name = name;
        this.price = price;
        this.createdAt = LocalDateTime.now();
    }

    // getters and setters omitted for brevity
}

import jakarta.persistence.*;

// PostgreSQL with SEQUENCE (recommended)
@Entity
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "order_seq")
    @SequenceGenerator(name = "order_seq", sequenceName = "order_id_seq", allocationSize = 50)
    private Long id;
    private String orderNumber;
}

// MySQL with IDENTITY (auto-increment)
@Entity
public class Customer {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;
    private String email;
}

// UUID generation (database-agnostic)
@Entity
public class Session {
    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;  // Java 17+ JPA feature
    private String token;
}

import jakarta.persistence.*;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Email;

@Entity
@Table(name = "users")
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Custom column name with NOT NULL constraint
    @Column(name = "user_name", nullable = false, length = 50)
    @NotNull  // Runtime validation
    private String username;

    // Unique email with custom length
    @Column(unique = true, length = 100)
    @Email
    private String email;

    // Custom SQL type definition
    @Column(columnDefinition = "TEXT")
    private String biography;

    // Default mapping (column name = fieldName)
    private Integer age;

    protected User() {}
}

import jakarta.persistence.*;
import java.time.*;
import java.util.Date;

@Entity
public class Event {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Modern approach: no @Temporal needed
    private LocalDate eventDate;           // Maps to DATE
    private LocalTime eventTime;           // Maps to TIME
    private LocalDateTime createdAt;       // Maps to TIMESTAMP
    private Instant lastModified;          // Maps to TIMESTAMP (UTC)

    // Legacy approach with @Temporal (avoid in new code)
    @Temporal(TemporalType.DATE)
    private Date birthDate;

    @Temporal(TemporalType.TIMESTAMP)
    private Date registeredAt;

    protected Event() {
        this.createdAt = LocalDateTime.now();
        this.lastModified = Instant.now();
    }
}

import jakarta.persistence.*;
import com.fasterxml.jackson.annotation.JsonIgnore;

@Entity
public class Customer {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String firstName;

    @Column(nullable = false)
    private String lastName;

    // Calculated field, not stored in database
    @Transient
    private String fullName;

    // Password field is persisted, but hash isn't serialized to JSON
    @Column(nullable = false)
    @JsonIgnore  // Prevents sending password in REST responses
    private String passwordHash;

    // Temporary state during processing
    @Transient
    private boolean emailSent;

    public String getFullName() {
        return firstName + " " + lastName;
    }
}
